drop table CHB_TRANS_MONTH;
CREATE TABLE
    CHB_TRANS_MONTH
    (
        REPORTUUID CHAR(36) NOT NULL,
        TERMID VARCHAR2(20),
        REPORTTYPE VARCHAR2(20),
        STARTDATE DATE,
        ENDDATE DATE,
        ISSUE_PARTY_ID VARCHAR2(50),
        ISSUE_PARTY_NAME VARCHAR2(50),
        REPORTFREQU VARCHAR2(2),
        SUBMIT_TIME DATE,
        CHB_SUBMIT_DEADLINE DATE,
        SUBMIT_DEADLINE DATE,
        SUBMIT_FEEDBACK_STATUS VARCHAR2(50),
        STATUS VARCHAR2(50),
        SEND_STATUS VARCHAR2(20),
        STATUS_DATE DATE,
        CREATE_USER VARCHAR2(20),
        CREATE_TIME TIMESTAMP(6),
        UPDATE_USER VARCHAR2(20),
        UPDATE_TIME TIMESTAMP(6),
        ORG_CODE VARCHAR2(20),
        DEPT_CODE VARCHAR2(20),
        CREATE_DEPT VARCHAR2(32),
        CONSTRAINT CHB_TRANS_MONTH_PK PRIMARY KEY (REPORTUUID)
    );
COMMENT ON TABLE CHB_TRANS_MONTH
IS
    '理财产品转型情况月度统计表';
COMMENT ON COLUMN CHB_TRANS_MONTH.REPORTUUID
IS
    '主键';
COMMENT ON COLUMN CHB_TRANS_MONTH.TERMID
IS
    '期数';
COMMENT ON COLUMN CHB_TRANS_MONTH.REPORTTYPE
IS
    '报表类型：MONTH-月报';
COMMENT ON COLUMN CHB_TRANS_MONTH.STARTDATE
IS
    '开始日期';
COMMENT ON COLUMN CHB_TRANS_MONTH.ENDDATE
IS
    '结束日期';
COMMENT ON COLUMN CHB_TRANS_MONTH.ISSUE_PARTY_ID
IS
    '发行机构代码';
COMMENT ON COLUMN CHB_TRANS_MONTH.ISSUE_PARTY_NAME
IS
    '发行机构名称';
COMMENT ON COLUMN CHB_TRANS_MONTH.REPORTFREQU
IS
    '报表频率';
COMMENT ON COLUMN CHB_TRANS_MONTH.SUBMIT_TIME
IS
    '报送日期';
COMMENT ON COLUMN CHB_TRANS_MONTH.CHB_SUBMIT_DEADLINE
IS
    '中债报送截止日';
COMMENT ON COLUMN CHB_TRANS_MONTH.SUBMIT_DEADLINE
IS
    '行内报送截止日';
COMMENT ON COLUMN CHB_TRANS_MONTH.SUBMIT_FEEDBACK_STATUS
IS
    '返回信息';
COMMENT ON COLUMN CHB_TRANS_MONTH.STATUS
IS
    '有效状态';
COMMENT ON COLUMN CHB_TRANS_MONTH.SEND_STATUS
IS
    '报送状态';
COMMENT ON COLUMN CHB_TRANS_MONTH.STATUS_DATE
IS
    '数据日期';
COMMENT ON COLUMN CHB_TRANS_MONTH.CREATE_USER
IS
    '创建人';
COMMENT ON COLUMN CHB_TRANS_MONTH.CREATE_TIME
IS
    '创建时间';
COMMENT ON COLUMN CHB_TRANS_MONTH.UPDATE_USER
IS
    '更新人';
COMMENT ON COLUMN CHB_TRANS_MONTH.UPDATE_TIME
IS
    '更新时间';
COMMENT ON COLUMN CHB_TRANS_MONTH.ORG_CODE
IS
    '机构代码';
COMMENT ON COLUMN CHB_TRANS_MONTH.DEPT_CODE
IS
    '部门代码';
COMMENT ON COLUMN CHB_TRANS_MONTH.CREATE_DEPT
IS
    '创建部门';

drop table CHB_TRANS_MONTH_DETAIL;
CREATE TABLE
    CHB_TRANS_MONTH_DETAIL
    (
        TERMID VARCHAR2(20),
        REPORTTYPE VARCHAR2(10),
        PROPERTYCODE VARCHAR2(20),
        NEW_BALANCE NUMBER(24,6),
        NEW_TERMS NUMBER(30,14),
        OLD_BALANCE NUMBER(24,6),
        OLD_TERMS NUMBER(30,14),
        DETAILUUID CHAR(36) NOT NULL,
        ORG_CODE VARCHAR2(20),
        DEPT_CODE VARCHAR2(20),
        REPORTUUID CHAR(36),
        CONSTRAINT CHB_TRANS_MONTH_DETAIL_PK PRIMARY KEY (DETAILUUID)
    );
COMMENT ON TABLE CHB_TRANS_MONTH_DETAIL
IS
    '理财转型月度报表明细表';
